/* From Uiverse.io by alexruix - Tags: switch, dark, light, theme-switch */
/* The switch - the box around the slider */
.__UIV_SCOPE__ .switch {
  font-size: 17px;
  position: relative;
  display: inline-block;
  width: 3.5em;
  height: 2em;
}

/* Hide default HTML checkbox */
.__UIV_SCOPE__ .switch input {
  opacity: 0;
  width: 0;
  height: 0;
}

/* The slider */
.__UIV_SCOPE__ .slider {
  --background: #28096b;
  position: absolute;
  cursor: pointer;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background-color: var(--background);
  transition: .5s;
  border-radius: 30px;
}

.__UIV_SCOPE__ .slider:before {
  position: absolute;
  content: "";
  height: 1.4em;
  width: 1.4em;
  border-radius: 50%;
  left: 10%;
  bottom: 15%;
  box-shadow: inset 8px -4px 0px 0px #fff000;
  background: var(--background);
  transition: .5s;
}

.__UIV_SCOPE__ input:checked + .slider {
  background-color: #522ba7;
}

.__UIV_SCOPE__ input:checked + .slider:before {
  transform: translateX(100%);
  box-shadow: inset 15px -4px 0px 15px #fff000;
}
